   "code": "from service_tracker.loader import load_visits\nimport deck\n\nROW = \"V-0999, sw-7777 ,switch,A. Okafor,2026-10-30,PWR,P-12345,1,fixed\"\nPATTERN = r\"^P-\\d{4}$\"      # part_number_pattern in settings.json\n\nheader = (\"visit_id,serial_number,equipment_type,technician,visit_date,\"\n          \"problem_code,part_number,quantity_used,outcome\")\nwith open(\"try.csv\", \"w\") as f:\n    f.write(header + \"\\n\" + ROW + \"\\n\")\n\nvisits, rejected = load_visits(\"try.csv\", PATTERN)\n\nfor r in rejected:\n    print(\"Rejected:\", r.reason)\n    deck.stats({\"Rejected\": 1}, tones={\"Rejected\": \"bad\"})\nfor v in visits:\n    print(\"Accepted:\", v)\n    deck.stats({\"Accepted\": 1}, tones={\"Accepted\": \"ok\"})\n    deck.table([{\"field\": k, \"saved as\": repr(val)} for k, val in vars(v).items()],\n               title=\"What the database would receive\", limit=9)\n",
