   "code": "from contextlib import closing\nfrom service_tracker.db import connect, init_db, load_stock_records, save_visits\nfrom service_tracker.loader import load_stock, load_visits\nimport deck\n\nvisits, _ = load_visits(\"data/visits.csv\", r\"^P-\\d{4}$\")\nstock, _ = load_stock(\"data/stock.csv\")\n\nwith closing(connect(deck.fresh_path(\"julian.db\"))) as conn:\n    init_db(conn)\n    count = lambda t: conn.execute(f\"SELECT COUNT(*) FROM {t}\").fetchone()[0]\n    tables = (\"equipment\", \"visits\", \"parts_used\", \"stock\")\n\n    load_stock_records(conn, stock)\n    before = {t: count(t) for t in tables}\n    on_hand_before = dict(conn.execute(\"SELECT part_number, quantity_on_hand FROM stock\"))\n\n    result = save_visits(conn, visits)\n\n    after = {t: count(t) for t in tables}\n    parts = conn.execute(\"SELECT * FROM stock ORDER BY part_number\").fetchall()\n\nprint(result)\ndeck.stock(\"Stock on hand: before and after this batch\", [\n    {\"part\": p[\"part_number\"], \"before\": on_hand_before[p[\"part_number\"]],\n     \"after\": p[\"quantity_on_hand\"], \"reorder\": p[\"reorder_level\"]} for p in parts])\ndeck.compare(\"Rows in each table\", before, after, \"Stock loaded\", \"After the batch\")\n",
